[CmdletBinding()]param()
$ErrorActionPreference='Stop';$repository=Split-Path $PSScriptRoot -Parent
$guest=Join-Path $repository 'harness\windows-sandbox\run-caption-proof.ps1';$config=Join-Path $repository 'harness\windows-sandbox\configs\beta-soak-proof.wsb';$hostScript=Join-Path $PSScriptRoot 'prove-beta-soak-in-owned-sandbox.ps1';$commissioningScript=Join-Path $PSScriptRoot 'prove-installed-commissioning.ps1';$assertions=0
function Assert-C([bool]$value,[string]$message){$script:assertions++;if(-not $value){throw "ASSERTION FAILED: $message"}}
foreach($path in @($guest,$hostScript,$commissioningScript)){ $t=$null;$e=$null;[Management.Automation.Language.Parser]::ParseFile($path,[ref]$t,[ref]$e)|Out-Null;Assert-C ($e.Count -eq 0) "$path must parse" }
[xml]$wsb=Get-Content -LiteralPath $config -Raw;$guestText=Get-Content $guest -Raw;$hostText=Get-Content $hostScript -Raw
Assert-C ($guestText -match 'ValidateSet\(''Caption'',''BetaSoak''\).*\$Mode=''Caption''' -and ($guestText|Select-String -AllMatches 'Start-Process -FilePath \$installerPath').Matches.Count -eq 1) 'beta mode must extend, not duplicate, the default caption install flow.'
Assert-C ($guestText -match 'if\(\$Mode -eq ''BetaSoak''\)\{Invoke-CombinedBetaSoak\}' -and $guestText -match 'configured channel stable healthy fallback') 'beta soak begins only after successful caption proof and healthy fallback.'
Assert-C ($guestText -match 'fresh_configuration_run' -and $guestText -match 'commissioning_result_sha256' -and $guestText -match 'candidate_manifest_sha256' -and $guestText -match 'station_revision') 'guest must produce exact commissioning/configuration bindings.'
Assert-C ($guestText -match 'prove-installed-commissioning\.ps1' -and $guestText -match '-FixturePath \$localFixture\.FullName' -and $guestText -match '-ResultPath \$commissioningPath' -and $guestText -notmatch '\$commissioning=\[ordered\]') 'guest must run and freeze the real commissioning proof, never fabricate a passed receipt.'
Assert-C ($guestText -match 'passed beta-soak run must not contain failure evidence') 'guest must reject failure evidence in a purported passed soak.'
Assert-C ($guestText -match 'Get-MappedPayloadManifestSha256' -and $guestText -match 'payload_manifest_sha256' -and $guestText -match 'Assert-SubstantiveCommissioningReceipt') 'guest must recompute the request payload manifest and require substantive commissioning evidence.'
Assert-C ($guestText -match 'prove-installed-beta-soak\.ps1' -and $guestText -match '-ExpectedStationRevision' -and $guestText -match '-ExpectedChannelState healthy_fallback' -and $guestText -match '-DurationHours \$DurationHours') 'guest must invoke the installed proof with exact bindings.'
Assert-C ($guestText -match 'FileMode\]::CreateNew' -and $guestText -match 'Copy-NewBoundedEvidence' -and $guestText -match 'observations\.ndjson' -and $guestText -match 'restart\.json' -and $guestText -match 'final-summary\.json') 'guest evidence must be bounded, create-new, and indexed.'
Assert-C ($guestText -match 'combined-failure\.json' -and $guestText -match 'shutdown\.exe' -and $guestText -match 'if \(\$result.status -ne ''passed''\)') 'guest failure must publish bounded redacted evidence and exit nonzero before shutdown.'
$mappings=@($wsb.Configuration.MappedFolders.MappedFolder);$writable=@($mappings|Where-Object{[string]$_.ReadOnly -eq 'false'})
Assert-C ([string]$wsb.Configuration.Networking -eq 'Disable' -and $mappings.Count -eq 6 -and $writable.Count -eq 1 -and [string]$writable[0].SandboxFolder -eq 'C:\TownLightEvidence') 'WSB must disable networking and expose only one writable evidence folder.'
Assert-C (@($mappings|Where-Object{[string]$_.SandboxFolder -ne 'C:\TownLightEvidence' -and [string]$_.ReadOnly -ne 'true'}).Count -eq 0 -and [string]$wsb.Configuration.LogonCommand.Command -match 'run-caption-proof\.ps1.*-Mode BetaSoak') 'all non-evidence mappings must be read-only and logon explicit.'
Assert-C ($hostText -match 'git -C \$repository status --porcelain' -and $hostText -match 'Get-TownLightCandidateIdentity' -and $hostText -match 'fixtureSize' -and $hostText -match 'fixtureSha256') 'host must freeze a clean candidate and exact fixture.'
Assert-C ($hostText -match '\$guard -CheckOnly' -and $hostText -match 'AddMinutes\(90\)' -and $hostText -match 'Min\(480' -and $hostText -match '\$guard -ConfigurationPath') 'host must poll the shared guard every eight minutes up to ninety, then use guarded launch.'
Assert-C ($hostText -notmatch '(?i)Stop-Process|taskkill|\.Kill\(|WindowsSandboxRemoteSession|reconnect|adopt' -and ($hostText|Select-String -AllMatches '\$guard -ConfigurationPath').Matches.Count -eq 1) 'host must never kill, reconnect, adopt, or bypass the guard.'
Assert-C ($hostText -match 'SetupTimeoutSeconds\+\(\$DurationHours\*3600\)\+1800' -and $hostText -match 'elapsed_seconds.*DurationHours\*3600' -and $hostText -match 'restart_count -ne 1' -and $hostText -match 'coverage_ratio -lt 0\.98') 'host timeout and pass checks must bind selected duration, coverage, and one restart.'
Assert-C ($hostText -match 'pin\.sha256 -cne \[string\]\$artifact\.sha256' -and $hostText -match 'size_bytes' -and $hostText -match 'required artifact is missing' -and $hostText -match 'source_commit -cne \$head') 'host must validate index, candidate, required set, sizes, and hashes.'
Assert-C ($hostText -match 'Open-PinnedFile' -and $hostText -match 'FileShare\]::Read' -and $hostText -match 'Copy-PinnedFile' -and $hostText -match 'New-ProtectedImmutableRoot') 'host must parse/hash from retained handles and return protected immutable copies.'
Assert-C ($hostText -match 'combined-failure\.json' -and $hostText -match 'failed early' -and $hostText -match 'Count -ne 6' -and $hostText -match 'no failure artifact') 'host must stop on early failures and reject pass indexes containing failure artifacts.'
Assert-C ($hostText -match 'Assert-NoReparsePath' -and $hostText -match 'Pinned input authority changed across guarded launch' -and $hostText -match 'authorityPins') 'host must reject reparse authority and pin/revalidate inputs across launch.'
Assert-C ($hostText -match 'pinnedMappings' -and $hostText -match 'Pinned WSB mapping differs from authority') 'host must revalidate every exact mapping from the pinned WSB bytes used at launch.'
Assert-C ($hostText -match 'Get-MappedPayloadSnapshot' -and $hostText -match 'Get-ChildItem.*-Recurse' -and $hostText -match 'fullPayloadSnapshot' -and $hostText -match 'terminalPayload' -and $hostText -match 'Mapped payload set or identity changed before terminal acceptance') 'host must recursively pin every mapped file and retain/revalidate the exact set through terminal acceptance.'
Assert-C ($hostText -match '\$transferred=\$false' -and $hostText -match 'if\(-not\$transferred\).*\$ownedPins' -and $hostText.IndexOf('$terminalPayload=Get-MappedPayloadSnapshot') -lt $hostText.IndexOf('$immutableAuthority=New-ProtectedImmutableRoot')) 'snapshot ownership must dispose on every pre-transfer failure and terminal authority must pass before accepted-evidence creation.'
Assert-C ($hostText.IndexOf('Open-ValidatedLaunchPayloadAuthority') -lt $hostText.IndexOf('$payloadAuthority=Open-ValidatedLaunchPayloadAuthority') -and $hostText.IndexOf('$payloadAuthority=Open-ValidatedLaunchPayloadAuthority') -gt $hostText.IndexOf('$guard -CheckOnly') -and $hostText -match 'finally \{foreach\(\$pin in @\(\$trackedPins\)' -and $hostText -match 'foreach\(\$pin in @\(\$authorityPins\)') 'complete payload pins must be acquired only in a safe-window launch attempt and disposed on every terminal path.'
Assert-C ($hostText -match 'New-OwnedDirectoryAcl' -and $hostText -match 'Assert-OwnedDirectoryAcl' -and $hostText -match 'AreAccessRulesProtected' -and $hostText -match 'Assert-OwnedDirectoryIdentity') 'host-owned accepted-evidence parent and leaf must have exact protected ACL and identity revalidation.'
Assert-C ($hostText -match 'payload_manifest_sha256' -and $hostText -match 'Test-SubstantiveCommissioningReceipt' -and $hostText -match 'commissioning_run_id' -and $hostText -match 'commissioning_result_sha256') 'host must bind mapped payload and substantive commissioning run/hash through request, configuration, index, and result.'
Assert-C ((Get-Content $commissioningScript -Raw) -match 'schema_version\s*=\s*1' -and (Get-Content $commissioningScript -Raw) -match "product\s*=\s*'TownLight Station'" -and (Get-Content $commissioningScript -Raw) -match "result_kind\s*=\s*'installed_commissioning'" -and (Get-Content $commissioningScript -Raw) -match 'Open-TownLightPinnedCaptionDecoder' -and (Get-Content $commissioningScript -Raw) -match '-ExpectedDecoderSha256' -and (Get-Content $commissioningScript -Raw) -match '-ExpectedDecoderSizeBytes' -and (Get-Content $commissioningScript -Raw) -match 'PinnedDecoderDirectoryHandles' -and (Get-Content (Join-Path $PSScriptRoot 'installed-caption-decoder-pin.ps1') -Raw) -match 'FILE_FLAG_BACKUP_SEMANTICS \| FILE_FLAG_OPEN_REPARSE_POINT') 'commissioning producer must emit the strict schema 1 product/result contract with a pinned private decoder and retained no-delete directory chain.'

function Test-HostileIndex([string]$Root,$Index){
 try{$seen=@{};foreach($a in @($Index.artifacts)){if([string]$a.name -notmatch '^beta-soak-[0-9a-f-]+-(commissioning|configuration|run-state|observations|restart|final-summary)\.(json|ndjson)$' -or $seen.ContainsKey([string]$a.name)){return $false};$seen[[string]$a.name]=$true;$p=Join-Path $Root ([string]$a.name);$i=Get-Item -LiteralPath $p -Force;if($i.PSIsContainer -or ($i.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne 0 -or $i.Length-ne[int64]$a.size_bytes -or (Get-FileHash $p -Algorithm SHA256).Hash.ToLowerInvariant()-cne[string]$a.sha256){return $false}};@($Index.artifacts|Where-Object{$_.name-like '*-final-summary.json'}).Count-eq1}catch{$false}
}
function Test-CommissioningFixture($Receipt,[string]$Commit){try{$e=$Receipt.evidence;$s=$e.schedule;$r=$e.restart_recovery;$d=$e.installed_identity.caption_decoder;[int]$Receipt.schema_version-eq1-and$Receipt.product-ceq'TownLight Station'-and$Receipt.result_kind-ceq'installed_commissioning'-and$Receipt.gate_status-ceq'passed'-and$Receipt.source_commit-ceq$Commit-and$e.installed_identity.source_commit-ceq$Commit-and$d.path-ceq'C:\Program Files\TownLight Station\runtime\caption-decoder\ffmpeg.exe'-and$d.sha256-cmatch'^[0-9a-f]{64}$'-and[int64]$d.size_bytes-gt0-and$e.cg.decoder_path-ceq$d.path-and$e.cg.decoder_sha256-ceq$d.sha256-and[int64]$e.cg.decoder_size_bytes-eq[int64]$d.size_bytes-and[int]$e.cg.decoder_directory_handle_count-eq4-and$e.services.station.state-eq'Running'-and$e.health_before_restart.status-eq'ready'-and$e.cg.clear_validated-eq$true-and$e.safe_to_air_before.color-eq'green'-and$e.media.readiness.readiness_state-eq'ready'-and$s.prepared.dry_run_passed-eq$true-and@($s.prepared.conflicts).Count-eq0-and((@($s.observed_statuses|Sort-Object -Unique)-join'|')-ceq'acknowledged|completed|pending|queued')-and$r.health.status-eq'ready'-and$r.safe_to_air.color-eq'green'-and$r.commit_report.dispatch_status-eq'completed'}catch{$false}}
function Test-ReparseFixture([IO.FileAttributes[]]$Chain){@($Chain|Where-Object{($_-band[IO.FileAttributes]::ReparsePoint)-ne0}).Count-eq0}
function Test-OwnedAuthorityFixture([bool]$Protected,[string[]]$Sids,[bool]$SameIdentity,[bool]$Reparse){$Protected-and-not$Reparse-and$SameIdentity-and(@($Sids|Sort-Object)-join'|')-ceq'S-1-5-18|S-1-5-32-544'}
function Test-PinDisposalFixture([string]$Terminal){$streams=@([IO.MemoryStream]::new(),[IO.MemoryStream]::new());try{if($Terminal-in@('lost_race','timeout','success')){throw $Terminal}}catch{}finally{foreach($stream in $streams){$stream.Dispose()}};try{$streams[0].WriteByte(1);$false}catch{$true}}
function Test-SnapshotNthOpenFailureDisposal{$root=Join-Path ([IO.Path]::GetTempPath()) ('beta-soak-nth-open-'+[guid]::NewGuid().ToString('N'));$first=Join-Path $root 'n.ps1';$second=Join-Path $root 'n-plus-1.ps1';[void][IO.Directory]::CreateDirectory($root);[IO.File]::WriteAllText($first,'one');[IO.File]::WriteAllText($second,'two');$owned=[Collections.Generic.List[object]]::new();try{try{foreach($path in @($first,$second)){if($path-ceq$second){throw 'deterministic n+1 open failure'};$owned.Add([IO.File]::Open($path,[IO.FileMode]::Open,[IO.FileAccess]::Read,[IO.FileShare]::Read))}}catch{}finally{foreach($stream in $owned){$stream.Dispose()}};[IO.File]::WriteAllText($first,'writable');Remove-Item -LiteralPath $first -Force;return -not(Test-Path $first)}finally{if(Test-Path $root){Remove-Item $root -Recurse -Force}}}
$fixture=Join-Path ([IO.Path]::GetTempPath()) ('beta-soak-static-'+[guid]::NewGuid().ToString('N'))
try{New-Item -ItemType Directory $fixture|Out-Null;$run='11111111-1111-4111-8111-111111111111';$arts=@();foreach($suffix in @('run-state.json','observations.ndjson','restart.json','final-summary.json')){$name="beta-soak-$run-$suffix";[IO.File]::WriteAllText((Join-Path $fixture $name),'{}',[Text.UTF8Encoding]::new($false));$arts+=[pscustomobject]@{name=$name;size_bytes=2;sha256=(Get-FileHash (Join-Path $fixture $name)-Algorithm SHA256).Hash.ToLowerInvariant()}};$index=[pscustomobject]@{artifacts=$arts};Assert-C (Test-HostileIndex $fixture $index) 'valid exact fixture set must pass';$lockedPath=Join-Path $fixture $arts[0].name;$locked=[IO.File]::Open($lockedPath,[IO.FileMode]::Open,[IO.FileAccess]::Read,[IO.FileShare]::Read);try{$bytes=[byte[]]::new([int]$locked.Length);[void]$locked.Read($bytes,0,$bytes.Length);$swapRejected=$false;try{[IO.File]::WriteAllText($lockedPath,'swapped')}catch{$swapRejected=$true};Assert-C ($swapRejected -and [Text.Encoding]::UTF8.GetString($bytes)-eq'{}') 'retained same-handle read must prevent path byte swap between hash and parse'}finally{$locked.Dispose()};$index.artifacts[0].sha256='0'*64;Assert-C (-not(Test-HostileIndex $fixture $index)) 'tampered hash must fail';$index.artifacts[0].name='..\escape.json';Assert-C (-not(Test-HostileIndex $fixture $index)) 'path traversal must fail';$failureName="beta-soak-$run-failure.json";[IO.File]::WriteAllText((Join-Path $fixture $failureName),'{}');$index.artifacts+= [pscustomobject]@{name=$failureName;size_bytes=2;sha256=(Get-FileHash (Join-Path $fixture $failureName)-Algorithm SHA256).Hash.ToLowerInvariant()};Assert-C (-not(Test-HostileIndex $fixture $index)) 'passed evidence containing a failure artifact must fail';$index.artifacts=@($index.artifacts|Where-Object{$_.name-notlike '*final-summary.json'});Assert-C (-not(Test-HostileIndex $fixture $index)) 'missing final summary must fail';$fabricated=[pscustomobject]@{gate_status='passed';evidence=[pscustomobject]@{installed_identity=[pscustomobject]@{source_commit='fake'};restart_recovery=[pscustomobject]@{status='passed'}}};Assert-C (-not(Test-CommissioningFixture $fabricated ('a'*40))) 'fabricated commissioning identity fixture must be rejected';Assert-C (-not(Test-ReparseFixture @([IO.FileAttributes]::Directory,[IO.FileAttributes]::ReparsePoint,[IO.FileAttributes]::Normal))) 'reparse ancestor fixture must be rejected';Assert-C (-not(Test-ReparseFixture @([IO.FileAttributes]::ReparsePoint))) 'reparse leaf/root fixture must be rejected'}finally{if(Test-Path $fixture){Remove-Item $fixture -Recurse -Force}}
$minimalBoundFabrication=[pscustomobject]@{schema_version=1;product='TownLight Station';result_kind='installed_commissioning';gate_status='passed';source_commit=('a'*40);evidence=[pscustomobject]@{installed_identity=[pscustomobject]@{source_commit=('a'*40)};restart_recovery=[pscustomobject]@{status='passed'}}}
Assert-C (-not(Test-CommissioningFixture $minimalBoundFabrication ('a'*40))) 'minimal fabricated commissioning fixture with matching identity must be rejected for absent substantive evidence.'
foreach($terminal in @('lost_race','timeout','success')){Assert-C (Test-PinDisposalFixture $terminal) "all pins must be disposed after deterministic $terminal terminal path"}
Assert-C (Test-SnapshotNthOpenFailureDisposal) 'when file N opens and file N+1 fails, file N must be immediately writable and deletable.'
Assert-C (-not(Test-OwnedAuthorityFixture $false @('S-1-5-18','S-1-5-32-544') $true $false)) 'hostile inherited/unprotected parent ACL fixture must be rejected.'
Assert-C (-not(Test-OwnedAuthorityFixture $true @('S-1-5-18','S-1-5-32-544') $false $false)) 'replaced parent/leaf identity fixture must be rejected.'
Assert-C (-not(Test-OwnedAuthorityFixture $true @('S-1-5-18','S-1-5-32-544') $true $true)) 'reparse parent/leaf fixture must be rejected.'
$nestedRoot=Join-Path ([IO.Path]::GetTempPath()) ('beta-soak-pinned-mapping-'+[guid]::NewGuid().ToString('N'));$nestedFile=Join-Path $nestedRoot 'scripts\nested\helper.ps1'
try{[void][IO.Directory]::CreateDirectory((Split-Path $nestedFile -Parent));[IO.File]::WriteAllText($nestedFile,'frozen',[Text.UTF8Encoding]::new($false));$nestedPin=[IO.File]::Open($nestedFile,[IO.FileMode]::Open,[IO.FileAccess]::Read,[IO.FileShare]::Read);try{$mutationRejected=$false;try{[IO.File]::WriteAllText($nestedFile,'changed')}catch{$mutationRejected=$true};Assert-C ($mutationRejected-and([IO.File]::ReadAllText($nestedFile)-ceq'frozen')) 'nested mapped helper mutation after pin/launch must not proceed or change bytes'}finally{$nestedPin.Dispose()}}finally{if(Test-Path $nestedRoot){Remove-Item $nestedRoot -Recurse -Force}}
"Windows Sandbox beta-soak harness passed ($assertions assertions; static/hostile-fixture only)."
